head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods26000";

// [A] 초기 목록 미해결 — jldods26000: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods26000.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_relatedLawList_oncellclick
 * @description grd_relatedLawList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_relatedLawList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_relatedLawList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_relatedLawList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.link(r["chrgInstId"], r["sprtRoomNo"], r["attachSeq"], r["attachFileNm"], r["sprtRoomContn"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_relatedLawList.oncellclick' });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name link
 * @description link 처리
 * @param {*} chrg_inst_id chrg_inst_id
 * @param {*} sprt_room_no sprt_room_no
 * @param {*} attach_seq attach_seq
 * @param {*} attach_file_nm attach_file_nm
 * @param {*} sprt_room_contn sprt_room_contn
 * @returns {void}
 * @hidden N
 */
scwin.link = function (chrg_inst_id, sprt_room_no, attach_seq, attach_file_nm, sprt_room_contn) {
    if (chrg_inst_id === "KRX") {
        scwin.fileDownload(sprt_room_no, attach_seq, attach_file_nm);
    } else {
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(sprt_room_contn), { id: 'popup' }, {});
    }
};

/**
 * @method
 * @name fileDownload
 * @description file Download 처리
 * @param {*} sprt_room_no sprt_room_no
 * @param {*} attach_seq attach_seq
 * @param {*} attach_file_nm attach_file_nm
 * @returns {void}
 * @hidden N
 */
scwin.fileDownload = function (sprt_room_no, attach_seq, attach_file_nm) {
    if (attach_seq === "") {
        return;
    }
    $('#ipt_sprtRoomNo', $('#attachForm')).val(sprt_room_no);
    $('#ipt_attachSeq', $('#attachForm')).val(attach_seq);
    $('#ipt_attachFileNm', $('#attachForm')).val(attach_file_nm);
    $('#ipt_SCREN_ID', $('#attachForm')).val("/jldods26000/jldods26000.xml");
    $('#ipt_method', $('#attachForm')).val("searchBbsAttachFile2");
    $('#attachForm').submit();
};
